from pathlib import Path
import base64, json, html, shutil
from PIL import Image

ROOT = Path(__file__).resolve().parent
REPO = ROOT.parent.parent
ASSETS = ROOT / 'assets'
manifest = []

def asset(name, source, crop=None, kind='existing'):
    source = Path(source)
    im = Image.open(source).convert('RGB')
    if crop:
        w,h=im.size
        im=im.crop(tuple(round(v*d) for v,d in zip(crop,(w,h,w,h))))
    im.thumbnail((1800,1800))
    out=ASSETS/(name+'.jpg')
    im.save(out,quality=91)
    manifest.append({'asset':out.name,'source':str(source),'type':kind,'crop_fraction':crop})
    return out

