def image(key,cls='',alt=''):
    path=ASSETS/(key+'.png' if key in ('logo','qr') else key+'.jpg')
    mime='image/png' if path.suffix=='.png' else 'image/jpeg'
    data=base64.b64encode(path.read_bytes()).decode()
    return f'<img class="{cls}" src="data:{mime};base64,{data}" alt="{html.escape(alt or key)}">'

def eyebrow(t): return f'<div class="eyebrow">{t}</div>'
def title(t,sub=''): return f'<h1>{t}</h1>'+ (f'<p class="lead">{sub}</p>' if sub else '')
def item(n,t,body): return f'<div class="item"><span>{n}</span><div><h3>{t}</h3><p>{body}</p></div></div>'
def caption(t): return f'<p class="caption">{t}</p>'
def scene(key): return '<figure class="scene">'+image(key,alt='AI生成的应用场景')+'<figcaption>AI 生成场景 · 非真实用户案例</figcaption></figure>'

pages=[]
def page(name,content,cls=''):
    n=len(pages)+1
    pages.append(f'<section class="page {cls}" id="p{n}" data-title="{name}"><header><span>图麦笔记</span><span>PRODUCT GUIDE / 2026</span></header><div class="content">{content}</div><footer><span>看到好内容，随手记下来。</span><span>{n:02d}</span></footer></section>')

